        const links = [{"text":"json-against-humanity","url":"https://github.com/crhallberg/json-against-humanity","rawHref":"https://github.com/crhallberg/json-against-humanity","category":"navigation","linkType":"external","containerLabel":"A party game for horrible people.","expectedStatus":null,"isVisible":true,"target":"_blank","targetBehavior":"new-tab","titleAttribute":"","downloadName":"","requiresAuth":false,"isSecure":true}];

